/**
 * ArvoBannerAlert -- persistent inline alert banner.
 *
 * Six semantic types (positive, info, neutral, warning, negative, block)
 * controlling left-border color, background tint, and icon glyph. Two layout
 * modes: default (title + multi-line message + optional link) and compact
 * (message only, tighter padding). Optionally dismissible via a 16x16
 * `ArvoIconButton` close affordance (variant="tertiary", size="xs") wired
 * through the `arvo-bnr-alert__close` BEM class -- positioning is handled by
 * the SCSS, the chrome (background, border, focus, icon glyph) comes from
 * the icon-button system. The component does NOT auto-remove itself on
 * dismiss; the consumer controls visibility in response to onDismiss.
 *
 * See descriptors/banner-alert.json for the full spec.
 */

import { forwardRef, useImperativeHandle, useRef } from 'react';
import type { HTMLAttributes, ReactNode } from 'react';
import ArvoIconButton from '../IconButton/IconButton';

// ---------------------------------------------------------------------------
// Public types
// ---------------------------------------------------------------------------

export type ArvoBannerAlertType =
  | 'positive'
  | 'info'
  | 'neutral'
  | 'warning'
  | 'negative'
  | 'block';

export type ArvoBannerAlertRole = 'status' | 'alert';

export interface ArvoBannerAlertProps
  extends Omit<HTMLAttributes<HTMLDivElement>, 'role' | 'title'> {
  /** Body message text. Required. */
  message: string;
  /** Semantic alert type. Defaults to "info". */
  type?: ArvoBannerAlertType;
  /** Optional title rendered above the message. Ignored in compact mode. */
  title?: string | null;
  /** Layout mode. When true, renders only the message with tighter padding. */
  isCompact?: boolean;
  /** Whether to render the close button on the right. Defaults to true. */
  isDismissible?: boolean;
  /** Optional link node rendered below the message. Ignored in compact mode. */
  link?: ReactNode;
  /** Pattern A shimmer loading state. */
  isLoading?: boolean;
  /**
   * Explicit ARIA role override. Defaults to "alert" for negative/block types
   * and "status" for all others.
   */
  role?: ArvoBannerAlertRole;
  /** Fired when the close button is clicked. */
  onDismiss?: () => void;
  /** Additional CSS classes appended to the root element. */
  className?: string;
}

// ---------------------------------------------------------------------------
// Helpers
// ---------------------------------------------------------------------------

// Types that auto-resolve to role="alert" (assertive live region) when the
// caller does not pass an explicit role prop.
const ASSERTIVE_TYPES: ReadonlySet<ArvoBannerAlertType> = new Set([
  'negative',
  'block',
]);

function resolveRole(
  type: ArvoBannerAlertType,
  roleProp: ArvoBannerAlertRole | undefined,
): ArvoBannerAlertRole {
  if (roleProp) return roleProp;
  return ASSERTIVE_TYPES.has(type) ? 'alert' : 'status';
}

// ---------------------------------------------------------------------------
// Component
// ---------------------------------------------------------------------------

export const ArvoBannerAlert = forwardRef<HTMLDivElement, ArvoBannerAlertProps>(
  function ArvoBannerAlert(
    {
      message,
      type = 'info',
      title = null,
      isCompact = false,
      isDismissible = true,
      link = null,
      isLoading = false,
      role: roleProp,
      onDismiss,
      className,
      ...rest
    },
    ref,
  ) {
    const resolvedRole = resolveRole(type, roleProp);

    // Hold an internal ref so handleDismiss can dispatch the bnr-alert:dismiss
    // CustomEvent on the root element (matches the JS implementation). The
    // forwarded ref is wired via useImperativeHandle, mirroring Drawer.tsx.
    const hostRef = useRef<HTMLDivElement | null>(null);
    useImperativeHandle(ref, () => hostRef.current as HTMLDivElement, []);

    const rootClasses = [
      'arvo-bnr-alert',
      `arvo-bnr-alert--${type}`,
      isCompact ? 'arvo-bnr-alert--compact' : '',
      isLoading ? 'loading' : '',
      className ?? '',
    ]
      .filter(Boolean)
      .join(' ');

    const handleDismiss = () => {
      const event = new CustomEvent('bnr-alert:dismiss', {
        bubbles: false,
        cancelable: false,
      });
      hostRef.current?.dispatchEvent(event);
      onDismiss?.();
    };

    const closeButton = isDismissible ? (
      <ArvoIconButton
        className="arvo-bnr-alert__close"
        variant="tertiary"
        size="xs"
        icon="close"
        tooltip="Dismiss alert"
        onClick={handleDismiss}
      />
    ) : null;

    return (
      <div
        ref={hostRef}
        className={rootClasses}
        role={resolvedRole}
        aria-busy={isLoading || undefined}
        {...rest}
      >
        <span className="arvo-bnr-alert__ico o9con" aria-hidden="true" />
        <div className="arvo-bnr-alert__content">
          {isCompact ? (
            <p className="arvo-bnr-alert__msg">{message}</p>
          ) : (
            <>
              <div className="arvo-bnr-alert__copy">
                {title != null && (
                  <p className="arvo-bnr-alert__title">{title}</p>
                )}
                <p className="arvo-bnr-alert__msg">{message}</p>
              </div>
              {link != null && (
                <div className="arvo-bnr-alert__link">{link}</div>
              )}
            </>
          )}
        </div>
        {closeButton}
      </div>
    );
  },
);

ArvoBannerAlert.displayName = 'ArvoBannerAlert';

export default ArvoBannerAlert;
